// Nimmt den Alertmanager-Webhook auseinander: nur firing, jede Meldung höchstens einmal je dedupeHours
// (Alertmanager wiederholt offene Alerts alle 12 h). Baut pro Alert die passende Loki-Abfrage.
const cfg = $('Config').first().json;
const body = $('Alert-Webhook').first().json.body || {};
const seen = $getWorkflowStaticData('global');
seen.fp = seen.fp || {};
const now = Date.now();
for (const k of Object.keys(seen.fp)) if (now - seen.fp[k] > cfg.dedupeHours * 3600e3) delete seen.fp[k];

const clean = s => String(s || '').toLowerCase().replace(/[^a-z0-9_.-]/g, '');
const hostOf = inst => String(inst || '').replace(/^[a-z]+:\/\//, '').split(/[:/]/)[0];
const ERR = '(?i)(error|err=|fatal|panic|fail|exception|refused|timeout|oom|killed)';

const out = [];
for (const a of body.alerts || []) {
  if (a.status !== 'firing') continue;
  const fp = a.fingerprint || JSON.stringify(a.labels);
  if (seen.fp[fp]) continue;
  seen.fp[fp] = now;

  const l = a.labels || {};
  const host = hostOf(l.instance);
  let logql, scope;
  if (l.name) {                                   // cadvisor-Alerts: Containername steht im Label
    logql = '{container="' + clean(l.name) + '"}';
    scope = 'Container ' + l.name;
  } else if (host && !/^\d+(\.\d+){3}$/.test(host) && !host.includes('.')) {   // Docker-Dienstname (z. B. n8n, node-exporter)
    const svc = clean(host);
    logql = '{container=~"(?i).*' + svc + '.*"}';
    scope = 'Container mit "' + svc + '" im Namen';
  } else {                                        // IP/Domain (Mac Studio, TLS-Probes) oder Host-Alert: Fehler aller Container
    logql = '{host="truenas"} |~ "' + ERR + '"';
    scope = 'Fehlermeldungen aller Container';
  }
  const startMs = Math.max(Date.parse(a.startsAt || now) - cfg.logMinutesBefore * 60e3, now - 3 * 3600e3);
  out.push({ json: {
    alertname: l.alertname, severity: l.severity, labels: l, annotations: a.annotations || {},
    startsAt: a.startsAt, logql, scope,
    start: String(startMs) + '000000', end: String(now) + '000000',
  } });
}
return out;

// Baut aus Alert + Logs die Anfrage an LM Studio (OpenAI-kompatibel).
const cfg = $('Config').first().json;
const a = $('Alerts aufbereiten').item.json;
const rows = [];
for (const s of $json.data?.result || []) for (const [ts, line] of s.values || []) rows.push([Number(ts.slice(0, 13)), s.stream?.container || '?', line]);
rows.sort((x, y) => x[0] - y[0]);
const fmt = ms => new Date(ms).toLocaleTimeString('de-DE', { timeZone: cfg.timezone });
let logs = rows.slice(-cfg.maxLogLines).map(([ms, c, l]) => fmt(ms) + ' ' + c + ': ' + l.replace(/\s+$/, '').slice(0, 300)).join('\n');
if (logs.length > 7000) logs = '…' + logs.slice(-7000);
const lokiError = $json.error ? (' (Loki-Fehler: ' + ($json.error.message || JSON.stringify($json.error)).slice(0, 200) + ')') : '';

const system = [
  'Du bist SRE für ein privates Homelab und erklärst Alerts kurz und konkret auf Deutsch.',
  'Umgebung: TrueNAS-NAS (Docker). Jeder Stack ist ein Compose-Projekt aus dem Git-Repo homelab-gitops, das Arcane automatisch deployt',
  '(Neustart: Arcane -> Stack -> Redeploy/Recreate; Env-Variablen kommen aus 1Password über scripts/render-env.sh).',
  'Stacks: traefik (Reverse Proxy, TLS), keycloak + oauth2-proxy (SSO), forgejo, paperless (+ paperless-ai), cloudflared (Tunnel),',
  'n8n (+ Postgres, SearXNG), observability (VictoriaMetrics, vmalert, Alertmanager, Loki, Alloy, Grafana, blackbox, node-exporter, cadvisor),',
  'garage (S3), zot/harbor (Registry), registry-cache, netboot, homepage. ZFS-Pools unter /mnt/fast, /mnt/data, /mnt/backup.',
  'LLMs laufen auf einem Mac Studio (192.168.80.30: Ollama :11434, LM Studio :1234), Doku docs/mac-studio-llm.md.',
  'Offsite-Backup: restic -> Backblaze B2 per Cron (docs/nas-backup/backup-offsite.sh).',
  'Antworte in genau drei Abschnitten, insgesamt höchstens 900 Zeichen, ohne Einleitung:',
  '**Was ist los:** ein Satz.',
  '**Wahrscheinliche Ursache:** aus den Logs abgeleitet. Zitiere die entscheidende Logzeile kurz. Geben die Logs nichts her, sag das ehrlich und nenne die plausibelste Ursache als Vermutung.',
  '**Nächste Schritte:** höchstens drei, konkret (Befehl oder Klickpfad).',
].join('\n');

const user = [
  'Alert: ' + a.alertname + ' (severity ' + a.severity + '), aktiv seit ' + a.startsAt,
  'Zusammenfassung: ' + (a.annotations.summary || '-'),
  'Labels: ' + JSON.stringify(a.labels),
  '',
  'Logs (' + a.scope + ', ' + rows.length + ' Zeilen, letzte ' + cfg.maxLogLines + ')' + lokiError + ':',
  logs || '(keine Logzeilen gefunden)',
].join('\n');

return { json: {
  ...a, logCount: rows.length,
  payload: { model: cfg.model, temperature: 0.2, max_tokens: 800,
             messages: [{ role: 'system', content: system }, { role: 'user', content: user }] },
} };

// LLM-Antwort -> Telegram-HTML. Fällt das LLM aus, kommt trotzdem eine Meldung mit den Eckdaten.
const a = $('Prompt bauen').item.json;
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
let txt = $json.choices?.[0]?.message?.content || '';
txt = txt.replace(/<think>[\s\S]*?<\/think>/g, '').trim();
const html = txt
  ? esc(txt).replace(/\*\*(.+?)\*\*/g, '<b>$1</b>').replace(/\x60([^\x60\n]+)\x60/g, '<code>$1</code>').replace(/^#+\s*/gm, '')
  : '⚠️ Keine Erklärung, LM Studio nicht erreichbar oder leere Antwort' + ($json.error ? ': ' + esc(($json.error.message || '').slice(0, 200)) : '') + '.';
const icon = { critical: '🔴', warning: '🟠' }[a.severity] || '🔵';
let text = '🧠 ' + icon + ' <b>' + esc(a.alertname) + '</b>\n<i>' + esc(a.annotations.summary || '') + '</i>\n\n' + html
  + '\n\n📜 ' + a.logCount + ' Logzeilen · <code>' + esc(a.logql) + '</code>';
if (text.length > 4000) text = text.slice(0, 3990) + '…';
return { json: { text } };
